templates.validate_current_interactive_after_actua:
$ErrorActionPreference='Stop'
$contextPath='evidence/080-interactive-assistantpref-agent-active-context-20261108.json'
$c=Get-Content -Raw $contextPath|ConvertFrom-Json -AsHashtable
if($c.actual_windows_exit_code-ne0 -or $c.status-cne'finished_pending_evidence_review'){throw 'Actual parent success required'}
function Read-Proof($name){Get-Content -Raw -LiteralPath (Join-Path $c.artifact_root $name)|ConvertFrom-Json -AsHashtable}
$r=Read-Proof 'receipt.json';$s=Read-Proof 'supervisor-report.json';$ctrl=Read-Proof 'controller-report.json';$results=Read-Proof 'interactive-results.json'
foreach($p in @($r,$s)){
 if(-not$p.passed -or -not$p.cleanup_complete -or $p.forced_cleanup -or $p.native_failure -or $p.child_returncode-ne0 -or -not$p.controller_exit_verified -or @($p.errors).Count -ne0){throw 'Receipt/supervisor final proof failed'}
}
if(-not$r.scope_empty_verified -or -not$r.supervisor_exit_verified -or $r.supervisor_returncode-ne0 -or $r.windows_proxy_returncode-ne0 -or $r.scope_cleanup_grace_seconds-lt30 -or $r.cleanup_grace_seconds-lt30 -or -not$r.sleep_inhibition.restored -or $r.power_monitor.changed -or $r.initial_boot_id-cne$r.final_boot_id -or @($r.new_wsl_dumps).Count -or @($r.new_kernel_fatals).Count){throw 'External final observation not clean'}
if(-not$ctrl.cleanup_complete -or $ctrl.forced_cleanup -or -not$ctrl.external_viewers_actual_exit_verified -or -not$ctrl.agent_acceptance_passed -or $ctrl.human_acceptance_passed -or -not$ctrl.oauth_phase_sync.passed -or -not$ctrl.oauth_cache_sync.passed -or -not$ctrl.oauth_cache_release.passed -or @($ctrl.errors).Count){throw 'UI/OAuth cleanup failed'}
if(-not$results.agent_acceptance_passed -or $results.human_acceptance_passed -or $results.observations.Count-ne8){throw 'Five agent tasks and three geometries required'}
foreach($ob in $results.observations.Values){if($ob.status-cne'passed'-or$ob.operator-cne'agent'-or$ob.human_reported){throw 'Wrong observation result/attribution'}}
$visual=Read-Proof 'root-visual-review.json'
if($visual.run_id-cne$c.run_id-or$visual.photos.Count-ne3-or-not$visual.root_personally_visually_reviewed){throw 'Actual root visual review required'}
foreach($photo in $visual.photos){
 if((Get-FileHash -LiteralPath $photo.png).Hash.ToLowerInvariant()-cne$photo.png_sha256){throw 'Viewed pixels changed'}
 $x=Read-Proof ('windows-observer-'+$photo.size+'-exit.json')
 if(-not$x.actual_exit_verified-or-not$x.readonly_observer_only-or$x.run_id-cne$c.run_id){throw 'Readonly observer actual exit missing'}
}
$operatorPath=Join-Path $c.artifact_root 'agent-operator-evidence.json'
if(-not(Test-Path -LiteralPath $operatorPath)){throw 'Detailed operator evidence missing'}
$appPath=Join-Path (Get-Location) 'evidence/080-app-ux-snapshot-active-context.json'
$a=Get-Content -Raw $appPath|ConvertFrom-Json -AsHashtable
if($a.freeze_sha256-cne$c.source_freeze_sha256){throw 'Active source differs'}
$report=@{schema_version=1;scope='devbrain_final_keyboard_and_windows_terminal_agent_acceptance';status='passed';run_id=$c.run_id;source_snapshot=$c.source_snapshot;source_freeze_sha256=$c.source_freeze_sha256;actual_windows_exec_session=85691;actual_windows_exit_code=0;receipt=(Join-Path $c.artifact_root 'receipt.json');receipt_sha256=(Get-FileHash -LiteralPath (Join-Path $c.artifact_root 'receipt.json')).Hash.ToLowerInvariant();artifact_root=$c.artifact_root;agent_acceptance_passed=$true;human_acceptance_passed=$false;five_tasks_passed=$true;three_real_geometries_passed=$true;english_default_and_polish_optional_verified=$true;native_process_preserved_on_resume=$true;assistant_choice_automatically_restored_without_reselection=$true;oauth_sync_and_release_passed=$true;cleanup_complete=$true;forced_cleanup=$false;scope_quiet_seconds=$r.scope_cleanup_grace_seconds;external_post_exit_seconds=$r.cleanup_grace_seconds;sleep_inhibition_restored=$true;power_changed=$false;native_failure=$false;initial_boot_id=$r.initial_boot_id;final_boot_id=$r.final_boot_id;photos=$visual.photos;operator_report=$operatorPath;operator_report_sha256=(Get-FileHash -LiteralPath $operatorPath).Hash.ToLowerInvariant();historical_results_pooled=$false;full_release_qualified=$false;continuous_eight_hours_qualified=$false;recorded_utc=[DateTime]::UtcNow.ToString('o')}
$reportPath=Join-Path (Get-Location) 'evidence/080-interactive-assistantpref-final-20261108.json'
if(Test-Path -LiteralPath $reportPath){throw 'Never overwrite final report'}
[IO.File]::WriteAllText($reportPath,($report|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))
$c.status='passed';$c.acceptance_passed=$true;$c.agent_acceptance_passed=$true;$c.human_acceptance_passed=$false;$c.cleanup_complete=$true;$c.receipt_sha256=$report.receipt_sha256;$c.receipt=$report.receipt;$c.final_report=$reportPath;$c.final_report_sha256=(Get-FileHash -LiteralPath $reportPath).Hash.ToLowerInvariant();$c.os_screenshot_claimed=$true;$c.actual_windows_exec_session=85691
[IO.File]::WriteAllText((Join-Path (Get-Location) $contextPath),($c|ConvertTo-Json -Depth 15),[Text.UTF8Encoding]::new($false))
$a.final_source_freeze=$true;$a.final_source_freeze_utc=[DateTime]::UtcNow.ToString('o');$a.final_ui_report_sha256=$c.final_report_sha256
[IO.File]::WriteAllText($appPath,($a|ConvertTo-Json -Depth 15),[Text.UTF8Encoding]::new($false))
[pscustomobject]@{status=$c.status;receipt_sha256=$c.receipt_sha256;report=$reportPath;sha256=$c.final_report_sha256;source_frozen=$true}|ConvertTo-Json
